	"g_vColorTint1"	"[1.000000 1.000000 1.000000 0.000000]"
	"g_vHighlightPositionWs1"	"[0.000000 0.000000 72.000000 0.000000]"
	"g_vHighlightTint1"	"[1.000000 1.000000 1.000000 0.000000]"
